using System;using Beast.Claw.Attributes;using Beast.Claw.Reflection;using Unity.Mathematics;using UnityEngine;namespace Beast.Claw.Common{    [DomainInitialize]    public static class BDebug    {        public static DebugTrackStorage StateStorage { get; }        static BDebug()        {            try            {                StateStorage = new DebugTrackStorage();            }            catch (Exception e)            {                InternalLogException(e);            }        }                public static void TrackInt<T>(T owner, string id, int value)        {            string detailedID = TypeStorage<T>.FullNameWithPostfixOrFullName(id);            StateStorage.WriteInt(detailedID, value);        }                public static void TrackFloat<T>(T owner, string id, float value)        {            string detailedID = TypeStorage<T>.FullNameWithPostfixOrFullName(id);                        StateStorage.WriteFloat(detailedID, value);        }        public static void TrackFloat2<T>(T owner, string id, float2 value)        {            string detailedID = TypeStorage<T>.FullNameWithPostfixOrFullName(id);            StateStorage.WriteFloat2(detailedID, value);        }                public static void TrackFloat3<T>(T owner, string id, float3 value)        {            string detailedID = TypeStorage<T>.FullNameWithPostfixOrFullName(id);            StateStorage.WriteFloat3(detailedID, value);        }                public static void TrackFloat4<T>(T owner, string id, float4 value)        {            string detailedID = TypeStorage<T>.FullNameWithPostfixOrFullName(id);            StateStorage.WriteFloat4(detailedID, value);        }                public static void TrackString<T>(T owner, string id, string value)        {            string detailedID = TypeStorage<T>.FullNameWithPostfixOrFullName(id);            StateStorage.WriteString(detailedID, value);        }                public static void LogInfo<T>(T owner, string message)        {            InternalLogInfo(TypeStorage<T>.FullName + ": " + message);        }                public static void LogError<T>(T owner, string message)        {            InternalLogError(TypeStorage<T>.FullName + ": " + message);        }                public static void LogStaticError(string message)        {            InternalLogError(message);        }        public static void LogException<T>(T owner, Exception e, string message)        {            InternalLogError(TypeStorage<T>.FullName + ": " + message);            InternalLogException(e);        }        public static void LogStaticException(Exception e, string message)        {            InternalLogError(message);            InternalLogException(e);        }        private static void InternalLogInfo(string message)        {            Debug.Log(message);        }                private static void InternalLogError(string message)        {            Debug.LogError(message);        }        private static void InternalLogException(Exception e)        {            Debug.LogException(e);        }    }}